CREATE TABLE "service_contracts"("id" SERIAL PRIMARY KEY,"number" TEXT NOT NULL UNIQUE,"name" TEXT NOT NULL,"customer_id" INTEGER NOT NULL REFERENCES "customers"("id"),"status" TEXT NOT NULL DEFAULT 'draft',"start_date" DATE NOT NULL,"end_date" DATE,"billing_day" INTEGER NOT NULL DEFAULT 10,"amount" DOUBLE PRECISION NOT NULL,"adjustment_index" TEXT,"next_billing_at" DATE NOT NULL,"sla_hours" INTEGER,"notes" TEXT,"created_by" TEXT NOT NULL,"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),"updated_at" TIMESTAMPTZ NOT NULL DEFAULT now());CREATE INDEX "service_contracts_status_next_billing_at_idx" ON "service_contracts"("status","next_billing_at");CREATE INDEX "service_contracts_customer_id_idx" ON "service_contracts"("customer_id");
CREATE TABLE "contract_cycles"("id" SERIAL PRIMARY KEY,"contract_id" INTEGER NOT NULL REFERENCES "service_contracts"("id") ON DELETE CASCADE,"reference" TEXT NOT NULL,"amount" DOUBLE PRECISION NOT NULL,"due_at" DATE NOT NULL,"status" TEXT NOT NULL DEFAULT 'generated',"title_id" INTEGER,"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE("contract_id","reference"));CREATE INDEX "contract_cycles_due_at_status_idx" ON "contract_cycles"("due_at","status");
CREATE TABLE "contract_adjustments"("id" SERIAL PRIMARY KEY,"contract_id" INTEGER NOT NULL REFERENCES "service_contracts"("id") ON DELETE CASCADE,"old_amount" DOUBLE PRECISION NOT NULL,"new_amount" DOUBLE PRECISION NOT NULL,"percentage" DOUBLE PRECISION NOT NULL,"reason" TEXT NOT NULL,"effective_at" DATE NOT NULL,"actor" TEXT NOT NULL,"created_at" TIMESTAMPTZ NOT NULL DEFAULT now());CREATE INDEX "contract_adjustments_contract_id_effective_at_idx" ON "contract_adjustments"("contract_id","effective_at");
